#!/usr/bin/env node
// bench/run.mjs — Playwright Chromium driver implementing research/04's
// M1a/M1b/M1c, M2a/M2b, M3a/M3b/M3c. M2c (bundle cost) is wired from
// the pre-computed bench/results/bundle-sizes.json (generated by
// bench/measure-bundle.mjs). M3d (brush-drag) is stubbed -- see the
// TODO below -- no migrated chart has a brush yet.
//
// M3b (sustained update throughput, research/04: "drive updates every frame
// for 5 s (live-data scenario); report achieved FPS and dropped-frame %")
// runs ONLY for charts in LIVE_CHARTS (currently liveline, per LOG D22 --
// it is that chart's primary metric). It is a separate page load with
// `?scenario=live` (the scenario keeps its push loop armed instead of
// running the QA freeze protocol), driving `window.__benchLiveTick()` once
// per rAF for the whole window -- identical driver behavior for all impls.
//
// Usage:
//   node bench/run.mjs --chart line --impl bklit --n 1000
//   node bench/run.mjs --all
//
// Integrity: this driver measures the REAL components as shipped (real
// seeded data at the requested n, real animations, real DOM). It does not
// shorten animations, reduce data, or mock components. If a chart renders
// slowly, that is the finding -- nothing here is tuned to make numbers look
// better.

import { chromium } from "playwright";
import { spawn } from "node:child_process";
import { mkdirSync, writeFileSync, existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const APP_DIR = path.join(ROOT, "bench", "app");
const RESULTS_DIR = path.join(ROOT, "bench", "results");
const PORT = 5199;
const BASE_URL = `http://localhost:${PORT}`;

// Load M2c bundle-size data (pre-computed by bench/measure-bundle.mjs)
const BUNDLE_SIZES_PATH = path.join(RESULTS_DIR, "bundle-sizes.json");
const bundleSizes = existsSync(BUNDLE_SIZES_PATH)
  ? JSON.parse(readFileSync(BUNDLE_SIZES_PATH, "utf-8"))
  : {};

const WARMUP_RUNS = 1;
const MEASURED_RUNS = 7;
const IDLE_MS = 5000; // M2a: 5s post-settle, no input
const UPDATE_TICKS = 30; // M3a
const HOVER_STEPS = 60; // M3c
const BRUSH_DRAG_STEPS = 60; // M3d (chart === "brush" only)
const M3B_WINDOW_MS = 5000; // M3b: sustained live-update window
const M3B_MEASURED_PASSES = 3; // M3b passes per combo (plus 1 warmup)
// Charts with a live-data mode; M3b only makes sense (and only runs) for
// these. Everything else keeps m3b_sustainedUpdate: null.
const LIVE_CHARTS = new Set(["liveline"]);

const CHARTS = ["line", "area", "bar", "scatter"];
const IMPLS = ["bklit", "tanstack"];
const PILOT_NS = [100, 1000, 10000];

// ---------------------------------------------------------------------- //
// CLI
// ---------------------------------------------------------------------- //

function parseArgs(argv) {
  const args = { all: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--all") args.all = true;
    else if (a === "--chart") args.chart = argv[++i];
    else if (a === "--impl") args.impl = argv[++i];
    else if (a === "--n") args.n = Number(argv[++i]);
    else if (a === "--base-url") args.baseUrl = argv[++i];
  }
  return args;
}

// ---------------------------------------------------------------------- //
// Stats helpers
// ---------------------------------------------------------------------- //

function median(nums) {
  if (nums.length === 0) return null;
  const s = [...nums].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 === 0 ? (s[mid - 1] + s[mid]) / 2 : s[mid];
}

function p95(nums) {
  if (nums.length === 0) return null;
  const s = [...nums].sort((a, b) => a - b);
  const idx = Math.min(s.length - 1, Math.ceil(0.95 * s.length) - 1);
  return s[idx];
}

function summarize(nums) {
  return { median: median(nums), p95: p95(nums), n: nums.length, values: nums };
}

// ---------------------------------------------------------------------- //
// Dev server bootstrap (build once, then `vite preview`)
// ---------------------------------------------------------------------- //

function run(cmd, args, opts = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, args, { stdio: "inherit", ...opts });
    child.on("exit", (code) => (code === 0 ? resolve() : reject(new Error(`${cmd} ${args.join(" ")} exited ${code}`))));
  });
}

async function waitForServer(url, timeoutMs = 20000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const res = await fetch(url);
      if (res.ok) return;
    } catch {
      // not up yet
    }
    await new Promise((r) => setTimeout(r, 250));
  }
  throw new Error(`Server at ${url} did not become ready within ${timeoutMs}ms`);
}

// Stale-build guard (D214, mirrors qa/screenshot.mjs): any source newer than
// dist/index.html forces a rebuild, BEFORE the already-running-server check —
// vite preview serves dist from disk, so a rebuild propagates to a reused
// server too. Prevents silently benchmarking a build older than the edits
// under test.
function newestSourceMtimeMs(dir) {
  let newest = 0;
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return 0;
  }
  for (const e of entries) {
    if (e.name === "node_modules" || e.name === "dist" || e.name.startsWith(".")) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) newest = Math.max(newest, newestSourceMtimeMs(p));
    else {
      try {
        newest = Math.max(newest, statSync(p).mtimeMs);
      } catch {
        // deleted mid-scan; ignore
      }
    }
  }
  return newest;
}

async function rebuildIfStale() {
  const distIndex = path.join(APP_DIR, "dist", "index.html");
  const distMtime = existsSync(distIndex) ? statSync(distIndex).mtimeMs : 0;
  const sourceRoots = [
    path.join(APP_DIR, "src"),
    path.join(APP_DIR, "index.html"),
    path.join(ROOT, "showcase", "migrated"),
    path.join(ROOT, "repos", "bklit-ui", "packages", "ui", "src"),
  ];
  const srcMtime = Math.max(
    ...sourceRoots.map((p) => {
      try {
        return statSync(p).isDirectory() ? newestSourceMtimeMs(p) : statSync(p).mtimeMs;
      } catch {
        return 0;
      }
    }),
  );
  if (distMtime === 0 || srcMtime > distMtime) {
    console.log(
      `[bench] bench/app dist ${distMtime === 0 ? "missing" : "STALE (sources newer than build)"} — rebuilding...`,
    );
    await run("npm", ["run", "build"], { cwd: APP_DIR });
  }
}

async function ensureServer(baseUrl) {
  await rebuildIfStale();
  try {
    const res = await fetch(baseUrl);
    if (res.ok) {
      console.log(`[bench] reusing already-running server at ${baseUrl}`);
      return { stop: async () => {} };
    }
  } catch {
    // not running, fall through to boot it
  }

  console.log(`[bench] starting vite preview on port ${PORT}...`);
  const child = spawn("npm", ["run", "preview", "--", "--port", String(PORT), "--strictPort"], {
    cwd: APP_DIR,
    stdio: "ignore",
  });
  await waitForServer(baseUrl);
  console.log(`[bench] server ready at ${baseUrl}`);
  return {
    stop: async () => {
      child.kill();
    },
  };
}

// ---------------------------------------------------------------------- //
// Per-run measurement
// ---------------------------------------------------------------------- //

function sceneUrl(baseUrl, { impl, chart, n, scenario }) {
  const base = `${baseUrl}/?impl=${impl}&chart=${chart}&n=${n}`;
  return scenario ? `${base}&scenario=${scenario}` : base;
}

/**
 * Sweep coordinates that track the actual rendered chart geometry, in
 * viewport (client) pixel coordinates directly usable by `page.mouse.move`.
 * See the M3c comment in `runOnce` for why this beats a fixed sweep line.
 */
async function getSweepPoints(page, chart, steps) {
  return page.evaluate(
    ({ chart, steps }) => {
      // Pick the LARGEST-area svg, not the first: the migrated hosts render a
      // 0x0 gradient-defs svg before the chart svg, and the brush scenario
      // composes a main chart + a 72px strip chart.
      const svgs = Array.from(document.querySelectorAll("#chart-root svg"));
      let svg = null;
      let bestArea = 0;
      for (const s of svgs) {
        const b = s.getBoundingClientRect();
        if (b.width * b.height > bestArea) {
          bestArea = b.width * b.height;
          svg = s;
        }
      }
      if (!svg) return [];

      const toClientFromSvgPoint = (svgPoint, el) => {
        const ctm = el.getScreenCTM();
        if (!ctm) return null;
        const p = svg.createSVGPoint();
        p.x = svgPoint.x;
        p.y = svgPoint.y;
        const transformed = p.matrixTransform(ctm);
        return { x: transformed.x, y: transformed.y };
      };

      const sampleAlongPath = (path) => {
        if (!path || typeof path.getTotalLength !== "function") return [];
        const len = path.getTotalLength();
        if (!(len > 0)) return [];
        const pts = [];
        for (let i = 0; i < steps; i++) {
          const svgPoint = path.getPointAtLength((len * i) / (steps - 1));
          const client = toClientFromSvgPoint(svgPoint, path);
          if (client) pts.push(client);
        }
        return pts;
      };

      const resampleCentered = (centers) => {
        if (centers.length === 0) return [];
        const sorted = [...centers].sort((a, b) => a.x - b.x);
        const pts = [];
        for (let i = 0; i < steps; i++) {
          const idx = Math.round((sorted.length - 1) * (i / (steps - 1)));
          pts.push(sorted[idx]);
        }
        return pts;
      };

      // "brush" composes a main line chart (the largest svg picked above) +
      // a strip chart; hover the main chart's line like the plain line chart.
      // "markers" (initiative 10, D229 ruling 10) is a plain Line host too
      // (showMarkers/dashFromIndex + a ChartMarkers overlay) -- same
      // path-sampling sweep applies. "patternarea" (initiative 11) is a
      // plain Area host (PatternArea's own fill mark + a zero-opacity
      // <Area> stroke sibling for the doc idiom) -- same area-family
      // path-sampling sweep applies.
      if (
        chart === "line" ||
        chart === "area" ||
        chart === "brush" ||
        chart === "markers" ||
        chart === "patternarea"
      ) {
        const path = svg.querySelector("path");
        return sampleAlongPath(path);
      }

      if (chart === "scatter") {
        const circles = Array.from(svg.querySelectorAll("circle")).filter(
          (c) => Number(c.getAttribute("r")) > 0,
        );
        const centers = circles.map((c) => {
          const b = c.getBoundingClientRect();
          return { x: b.x + b.width / 2, y: b.y + b.height / 2 };
        });
        return resampleCentered(centers);
      }

      // "barsquares" (BarSquares/BarColumnTrack) and "bardepth" (BarDepth/
      // BarPulse) are both bar-family hosts (initiative 11) -- reuse the
      // same rect-top sampling. Note this is an approximation for
      // "barsquares": each bar is rendered as a STACK of small quantized
      // square rects (not one tall rect), so the `width < svgWidth*0.5`
      // filter picks up every square cell, not one point per bar/group --
      // still a representative hover sweep across the plot, just denser
      // than the plain "bar" case.
      if (chart === "bar" || chart === "barsquares" || chart === "bardepth") {
        // Hover near the TOP edge of each bar (the actual data-value anchor
        // TanStack's proximity hit-test uses), not the rect's vertical
        // center -- for a short bar sitting near the baseline, the center
        // can already be > maxFocusDistance away from that anchor.
        const svgWidth = svg.getBoundingClientRect().width;
        const rects = Array.from(svg.querySelectorAll("rect")).filter((r) => {
          const b = r.getBoundingClientRect();
          return b.width > 0 && b.height > 0 && b.width < svgWidth * 0.5;
        });
        const tops = rects.map((r) => {
          const b = r.getBoundingClientRect();
          return { x: b.x + b.width / 2, y: b.y + Math.min(4, b.height / 2) };
        });
        return resampleCentered(tops);
      }

      return [];
    },
    { chart, steps },
  );
}

/** CDP Performance.getMetrics() as a name->value map. */
async function getMetrics(cdp) {
  const { metrics } = await cdp.send("Performance.getMetrics");
  const map = {};
  for (const m of metrics) map[m.name] = m.value;
  return map;
}

async function runOnce(browser, params) {
  const context = await browser.newContext({ viewport: { width: 1200, height: 800 } });
  const page = await context.newPage();
  const cdp = await context.newCDPSession(page);
  await cdp.send("Performance.enable");
  await cdp.send("HeapProfiler.enable");

  const consoleErrors = [];
  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text());
  });
  page.on("pageerror", (err) => consoleErrors.push(String(err)));

  const metricsBeforeNav = await getMetrics(cdp);
  const navStart = Date.now();
  await page.goto(sceneUrl(params.__baseUrl, params), { waitUntil: "commit" });

  // M1a: mount-to-paint, read straight from the in-page performance measure.
  await page.waitForFunction(() => window.__benchPaintDone === true, { timeout: 30000 });
  const m1a = await page.evaluate(() => {
    const entry = performance.getEntriesByName("bench:mount-to-paint")[0];
    return entry ? entry.duration : null;
  });

  // M1b: settle time, measured against the same render-start mark.
  const m1b = await page.evaluate(async () => {
    await window.__benchSettled;
    const startEntry = performance.getEntriesByName("bench:render-start")[0];
    return startEntry ? performance.now() - startEntry.startTime : null;
  });

  // M1c: main-thread scripting cost of the mount window (nav -> settle).
  const metricsAfterMount = await getMetrics(cdp);
  const m1cScriptMs = (metricsAfterMount.ScriptDuration - metricsBeforeNav.ScriptDuration) * 1000;
  const m1cTaskMs = (metricsAfterMount.TaskDuration - metricsBeforeNav.TaskDuration) * 1000;

  // Sanity: verify the chart actually rendered (non-empty SVG, plausible
  // element counts) before trusting any measurement from this run.
  const renderCheck = await page.evaluate(() => {
    const root = document.getElementById("chart-root");
    // Some charts (bklit funnel family) render one <svg> per segment rather
    // than a single chart svg, so the check aggregates across ALL svgs under
    // the root: total drawable shapes, and the largest positive bounding box.
    const svgs = root ? Array.from(root.querySelectorAll("svg")) : [];
    if (svgs.length === 0) return { ok: false, reason: "no <svg> found" };
    let shapeCount = 0;
    let width = 0;
    let height = 0;
    for (const svg of svgs) {
      shapeCount += svg.querySelectorAll("path, circle, rect, line").length;
      const bbox = svg.getBoundingClientRect();
      if (bbox.width * bbox.height > width * height) {
        width = bbox.width;
        height = bbox.height;
      }
    }
    if (width <= 0 || height <= 0) {
      return { ok: false, reason: "svg has zero size" };
    }
    if (shapeCount === 0) {
      return { ok: false, reason: "svg has no drawable shapes" };
    }
    return { ok: true, width, height, shapeCount };
  });
  if (!renderCheck.ok) {
    await context.close();
    throw new Error(
      `render check failed for ${params.impl}/${params.chart} n=${params.n}: ${renderCheck.reason}`,
    );
  }

  // M2a: idle CPU -- 5s of no input, post-settle.
  const metricsBeforeIdle = await getMetrics(cdp);
  await page.waitForTimeout(IDLE_MS);
  const metricsAfterIdle = await getMetrics(cdp);
  const m2aScriptMs = (metricsAfterIdle.ScriptDuration - metricsBeforeIdle.ScriptDuration) * 1000;
  const m2aTaskMs = (metricsAfterIdle.TaskDuration - metricsBeforeIdle.TaskDuration) * 1000;

  // M2b: heap, after forced GC.
  await cdp.send("HeapProfiler.collectGarbage");
  const heap = await cdp.send("Runtime.getHeapUsage");

  // M3a: data-update latency, over 30 seeded dataset swaps.
  const updateDurations = [];
  for (let i = 0; i < UPDATE_TICKS; i++) {
    const dur = await page.evaluate(() => window.__benchUpdate());
    updateDurations.push(dur);
  }

  // M3c: hover cost. 60-step pointer sweep across the plot area at a fixed
  // cadence; frame times captured via an in-page rAF timestamp recorder.
  //
  // The sweep coordinates track the ACTUAL rendered mark geometry (sampled
  // along the line/area <path>, or centered on scatter <circle>s / bar
  // <rect>s) rather than a fixed horizontal line. This matters because the
  // two impls use genuinely different hover-hit-testing models: bklit's
  // crosshair tooltip is x-column-nearest and y-agnostic (any y in the
  // plot triggers it), but TanStack's default tooltip is proximity-based
  // (`maxFocusDistance`, ~48px in both x AND y from an actual mark -- see
  // charts-core/src/renderer.ts `pointsAtPointer`/`resolvePointerFocus`).
  // A fixed-height sweep line reliably missed TanStack's line/area curve
  // whenever the (random-walk seeded) data value was far from vertical
  // center, causing spurious "no tooltip" results that were an artifact of
  // the sweep path, not a real difference in either impl's hover behavior.
  // Sweeping along the real geometry is the fairer, more realistic test for
  // both, and is what a real user's cursor would actually be near.
  // Largest-area svg (matches getSweepPoints): the migrated hosts render a
  // 0x0 gradient-defs svg first, and the brush scenario has a strip chart.
  const svgBox = await page.evaluate(() => {
    let best = null;
    let bestArea = 0;
    for (const s of document.querySelectorAll("#chart-root svg")) {
      const b = s.getBoundingClientRect();
      if (b.width * b.height > bestArea) {
        bestArea = b.width * b.height;
        best = { x: b.x, y: b.y, width: b.width, height: b.height };
      }
    }
    return best;
  });
  await page.evaluate(() => {
    window.__benchFrames = [];
    window.__benchFrameRaf = true;
    const tick = (t) => {
      window.__benchFrames.push(t);
      if (window.__benchFrameRaf) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });
  // NOTE: a naive "any absolutely/fixed-positioned element with text" check
  // is NOT a reliable before/after signal here -- bklit's static x-axis tick
  // labels are themselves absolutely-positioned HTML overlay divs present
  // from mount, independent of hover. Use total text content length of
  // #chart-root instead: hovering genuinely adds new text (bklit's portaled
  // tooltip rows + date pill; tanstack's `.ts-chart-tooltip` div), so a
  // meaningful length increase is a reliable, impl-agnostic signal.
  const tooltipBefore = await page.evaluate(() => {
    const root = document.getElementById("chart-root");
    return (root.textContent || "").length;
  });
  const metricsBeforeHover = await getMetrics(cdp);
  const sweepPoints = await getSweepPoints(page, params.chart, HOVER_STEPS);
  if (sweepPoints.length >= 2) {
    await page.mouse.move(sweepPoints[0].x, sweepPoints[0].y);
    for (const pt of sweepPoints) {
      await page.mouse.move(pt.x, pt.y);
      await new Promise((r) => setTimeout(r, 16)); // ~60Hz input cadence
    }
  } else {
    // Fallback: no mark geometry found (shouldn't happen for the pilot
    // charts -- render-check above already asserts shapeCount > 0). Sweep a
    // fixed horizontal line through the plot center rather than fail M3c
    // outright.
    const cx = svgBox.x + svgBox.width / 2;
    const cy = svgBox.y + svgBox.height / 2;
    const sweepWidth = svgBox.width * 0.6;
    await page.mouse.move(cx - sweepWidth / 2, cy);
    for (let i = 0; i < HOVER_STEPS; i++) {
      const x = cx - sweepWidth / 2 + (sweepWidth * i) / (HOVER_STEPS - 1);
      await page.mouse.move(x, cy);
      await new Promise((r) => setTimeout(r, 16));
    }
  }
  const metricsAfterHover = await getMetrics(cdp);
  // The tooltip commit is scheduled one rAF tick after the last relevant
  // mousemove (see use-scheduled-tooltip.ts / tanstack's own render cycle);
  // give it a couple of real frames to land before asserting, decoupled
  // from the metrics window captured just above so this wait doesn't skew
  // the M3c scripting-cost numbers.
  await page.waitForTimeout(150);
  const tooltipAfter = await page.evaluate(() => {
    const root = document.getElementById("chart-root");
    return (root.textContent || "").length;
  });
  const tooltipAppeared = tooltipAfter - tooltipBefore >= 3;

  const frameTimestamps = await page.evaluate(() => {
    window.__benchFrameRaf = false;
    return window.__benchFrames;
  });
  const frameTimes = [];
  for (let i = 1; i < frameTimestamps.length; i++) {
    frameTimes.push(frameTimestamps[i] - frameTimestamps[i - 1]);
  }
  const m3cScriptMs = (metricsAfterHover.ScriptDuration - metricsBeforeHover.ScriptDuration) * 1000;
  const m3cPerMoveScriptMs = m3cScriptMs / HOVER_STEPS;

  // M3d (chart === "brush" only): a REAL pointer drag of the right brush
  // handle from the full-extent edge to 45% of the track, mouse.down ->
  // BRUSH_DRAG_STEPS moves at ~60Hz -> mouse.up. Both impls live-commit the
  // xDomain on every drag move (bklit onChange + D227 ruling 4 for the
  // migrated port), so ScriptDuration-delta / steps is the honest per-move
  // drag cost for both, same collection model as M3c. The strip container
  // is the BrushLayout/ChartBrushLayout fixed-height div (72px inline style
  // in both scenarios); its plot margins are the scenarios' shared
  // brushStripMargin {left:40, right:40}.
  let m3dPerMoveScriptMs = null;
  let m3dFrameTimes = null;
  let m3dDomainChanged = null;
  if (params.chart === "brush") {
    const strip = await page.evaluate(() => {
      const root = document.getElementById("chart-root");
      const divs = root ? root.querySelectorAll("div") : [];
      for (const el of divs) {
        if (el.style && el.style.height === "72px") {
          const r = el.getBoundingClientRect();
          return { x: r.x, y: r.y, width: r.width, height: r.height };
        }
      }
      return null;
    });
    if (strip && strip.width > 120) {
      // Main-chart x-axis labels change when the committed domain narrows;
      // compare the full root text before/after as the functional signal
      // (tooltipAppeared's impl-agnostic-text-signal precedent above).
      const rootTextBefore = await page.evaluate(() => {
        const root = document.getElementById("chart-root");
        return root.textContent || "";
      });
      const STRIP_MARGIN_X = 40;
      const innerW = strip.width - STRIP_MARGIN_X * 2;
      const yMid = strip.y + strip.height / 2;
      const startX = strip.x + STRIP_MARGIN_X + innerW;
      const endX = strip.x + STRIP_MARGIN_X + innerW * 0.45;
      await page.evaluate(() => {
        window.__benchFrames = [];
        window.__benchFrameRaf = true;
        const tick = (t) => {
          window.__benchFrames.push(t);
          if (window.__benchFrameRaf) requestAnimationFrame(tick);
        };
        requestAnimationFrame(tick);
      });
      const metricsBeforeDrag = await getMetrics(cdp);
      await page.mouse.move(startX, yMid);
      await page.mouse.down();
      for (let i = 1; i <= BRUSH_DRAG_STEPS; i++) {
        const x = startX + ((endX - startX) * i) / BRUSH_DRAG_STEPS;
        await page.mouse.move(x, yMid);
        await new Promise((r) => setTimeout(r, 16));
      }
      await page.mouse.up();
      const metricsAfterDrag = await getMetrics(cdp);
      // Let the final commit's render/tween land before the text check,
      // outside the metrics window (same decoupling as the tooltip check).
      await page.waitForTimeout(150);
      const dragFrameTs = await page.evaluate(() => {
        window.__benchFrameRaf = false;
        return window.__benchFrames;
      });
      m3dFrameTimes = [];
      for (let i = 1; i < dragFrameTs.length; i++) {
        m3dFrameTimes.push(dragFrameTs[i] - dragFrameTs[i - 1]);
      }
      m3dPerMoveScriptMs =
        ((metricsAfterDrag.ScriptDuration - metricsBeforeDrag.ScriptDuration) * 1000) /
        BRUSH_DRAG_STEPS;
      const rootTextAfter = await page.evaluate(() => {
        const root = document.getElementById("chart-root");
        return root.textContent || "";
      });
      m3dDomainChanged = rootTextAfter !== rootTextBefore;
    }
  }

  await context.close();

  return {
    m1a_mountToPaintMs: m1a,
    m1b_settleMs: m1b,
    m1c_scriptMs: m1cScriptMs,
    m1c_taskMs: m1cTaskMs,
    m2a_idleScriptMs: m2aScriptMs,
    m2a_idleTaskMs: m2aTaskMs,
    m2b_heapUsedBytes: heap.usedSize,
    m2b_heapTotalBytes: heap.totalSize,
    m3a_updateMs: updateDurations,
    m3c_frameTimesMs: frameTimes,
    m3c_perMoveScriptMs: m3cPerMoveScriptMs,
    m3c_tooltipAppeared: tooltipAppeared,
    m3d_perMoveScriptMs: m3dPerMoveScriptMs,
    m3d_frameTimesMs: m3dFrameTimes,
    m3d_domainChanged: m3dDomainChanged,
    renderCheck,
    consoleErrors,
    navToNowMs: Date.now() - navStart,
  };
}

// ---------------------------------------------------------------------- //
// M3b: sustained update throughput (LIVE_CHARTS only)
// ---------------------------------------------------------------------- //
//
// Separate page load with ?scenario=live. The driver calls the scenario's
// `window.__benchLiveTick()` (one seeded data push) at the top of EVERY
// animation frame for M3B_WINDOW_MS, recording rAF timestamps. Achieved
// FPS and dropped-frame % come straight from those timestamps; CDP
// TaskDuration/ScriptDuration bracket the window for main-thread cost.
// Identical driver behavior for every impl -- nothing here favors any
// implementation.
async function runM3bOnce(browser, params) {
  const context = await browser.newContext({ viewport: { width: 1200, height: 800 } });
  const page = await context.newPage();
  const cdp = await context.newCDPSession(page);
  await cdp.send("Performance.enable");

  const consoleErrors = [];
  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text());
  });
  page.on("pageerror", (err) => consoleErrors.push(String(err)));

  await page.goto(sceneUrl(params.__baseUrl, { ...params, scenario: "live" }), { waitUntil: "commit" });
  await page.waitForFunction(() => window.__benchPaintDone === true, { timeout: 30000 });
  await page.evaluate(async () => {
    await window.__benchSettled;
  });

  const metricsBefore = await getMetrics(cdp);
  const result = await page.evaluate(async (windowMs) => {
    if (typeof window.__benchLiveTick !== "function") {
      return { error: "scenario did not expose __benchLiveTick" };
    }
    const frames = [];
    const t0 = performance.now();
    await new Promise((resolve) => {
      function tick(t) {
        window.__benchLiveTick();
        frames.push(t);
        if (performance.now() - t0 < windowMs) requestAnimationFrame(tick);
        else resolve();
      }
      requestAnimationFrame(tick);
    });
    return { frames, elapsedMs: performance.now() - t0 };
  }, M3B_WINDOW_MS);
  const metricsAfter = await getMetrics(cdp);
  await context.close();

  if (result.error) {
    throw new Error(`[m3b] ${params.impl}/${params.chart} n=${params.n}: ${result.error}`);
  }

  const deltas = [];
  for (let i = 1; i < result.frames.length; i++) {
    deltas.push(result.frames[i] - result.frames[i - 1]);
  }
  const dropped = deltas.filter((d) => d > 33.4).length;
  return {
    fps: result.frames.length / (result.elapsedMs / 1000),
    droppedFramePct: deltas.length ? (dropped / deltas.length) * 100 : null,
    frameTimeMedianMs: median(deltas),
    frameTimeP95Ms: p95(deltas),
    taskMs: (metricsAfter.TaskDuration - metricsBefore.TaskDuration) * 1000,
    scriptMs: (metricsAfter.ScriptDuration - metricsBefore.ScriptDuration) * 1000,
    consoleErrors,
  };
}

// ---------------------------------------------------------------------- //
// Aggregate one (impl, chart, n) combo across warmup + measured runs
// ---------------------------------------------------------------------- //

async function benchOne(browser, baseUrl, { impl, chart, n }) {
  const params = { impl, chart, n, __baseUrl: baseUrl };
  const runs = [];
  const total = WARMUP_RUNS + MEASURED_RUNS;
  for (let i = 0; i < total; i++) {
    const label = i < WARMUP_RUNS ? "warmup" : `measured ${i - WARMUP_RUNS + 1}/${MEASURED_RUNS}`;
    process.stdout.write(`  [${impl}/${chart} n=${n}] run ${i + 1}/${total} (${label})... `);
    const t0 = Date.now();
    const r = await runOnce(browser, params);
    console.log(`done in ${Date.now() - t0}ms`);
    if (i >= WARMUP_RUNS) runs.push(r);
  }

  const m1a = summarize(runs.map((r) => r.m1a_mountToPaintMs).filter((v) => v != null));
  const m1b = summarize(runs.map((r) => r.m1b_settleMs).filter((v) => v != null));
  const m1cScript = summarize(runs.map((r) => r.m1c_scriptMs));
  const m1cTask = summarize(runs.map((r) => r.m1c_taskMs));
  const m2aScript = summarize(runs.map((r) => r.m2a_idleScriptMs));
  const m2aTask = summarize(runs.map((r) => r.m2a_idleTaskMs));
  const m2bHeap = summarize(runs.map((r) => r.m2b_heapUsedBytes));
  const allUpdates = runs.flatMap((r) => r.m3a_updateMs);
  const m3a = summarize(allUpdates);
  const allFrameTimes = runs.flatMap((r) => r.m3c_frameTimesMs);
  const m3cFrame = summarize(allFrameTimes);
  const m3cWorst = allFrameTimes.length ? Math.max(...allFrameTimes) : null;
  const m3cPerMove = summarize(runs.map((r) => r.m3c_perMoveScriptMs));
  const tooltipAppearedEveryRun = runs.every((r) => r.m3c_tooltipAppeared);
  const m3dRuns = runs.filter((r) => r.m3d_perMoveScriptMs != null);
  let m3d = null;
  if (m3dRuns.length) {
    const allDragFrames = m3dRuns.flatMap((r) => r.m3d_frameTimesMs);
    m3d = {
      dragSteps: BRUSH_DRAG_STEPS,
      perMoveScriptMs: summarize(m3dRuns.map((r) => r.m3d_perMoveScriptMs)),
      frameTimeMs: summarize(allDragFrames),
      worstFrameMs: allDragFrames.length ? Math.max(...allDragFrames) : null,
      domainChangedEveryRun: m3dRuns.every((r) => r.m3d_domainChanged),
      runsMeasured: m3dRuns.length,
    };
  }
  const consoleErrors = runs.flatMap((r) => r.consoleErrors);

  // M3b, live charts only (separate ?scenario=live page loads).
  let m3b = null;
  if (LIVE_CHARTS.has(chart)) {
    const passes = [];
    const totalPasses = 1 + M3B_MEASURED_PASSES;
    for (let i = 0; i < totalPasses; i++) {
      const label = i === 0 ? "warmup" : `measured ${i}/${M3B_MEASURED_PASSES}`;
      process.stdout.write(`  [${impl}/${chart} n=${n}] m3b pass ${i + 1}/${totalPasses} (${label})... `);
      const t0 = Date.now();
      const r = await runM3bOnce(browser, params);
      console.log(`done in ${Date.now() - t0}ms (fps ${r.fps.toFixed(1)})`);
      if (i > 0) passes.push(r);
      consoleErrors.push(...r.consoleErrors);
    }
    m3b = {
      windowMs: M3B_WINDOW_MS,
      fps: summarize(passes.map((p) => p.fps)),
      droppedFramePct: summarize(passes.map((p) => p.droppedFramePct).filter((v) => v != null)),
      frameTimeMedianMs: summarize(passes.map((p) => p.frameTimeMedianMs).filter((v) => v != null)),
      frameTimeP95Ms: summarize(passes.map((p) => p.frameTimeP95Ms).filter((v) => v != null)),
      taskMs: summarize(passes.map((p) => p.taskMs)),
      scriptMs: summarize(passes.map((p) => p.scriptMs)),
    };
  }

  return {
    impl,
    chart,
    n,
    warmupRuns: WARMUP_RUNS,
    measuredRuns: MEASURED_RUNS,
    metrics: {
      m1a_mountToPaintMs: m1a,
      m1b_settleMs: m1b,
      m1c_scriptMs: m1cScript,
      m1c_taskMs: m1cTask,
      m2a_idleScriptMs: m2aScript,
      m2a_idleTaskMs: m2aTask,
      m2b_heapUsedBytes: m2bHeap,
      m2c_bundleCost: bundleSizes[`${impl}/${chart}`] ?? null,
      m3a_updateMs: m3a,
      m3b_sustainedUpdate: m3b, // null for non-live charts (see LIVE_CHARTS)
      m3c_frameTimeMs: { median: m3cFrame.median, worst: m3cWorst, p95: m3cFrame.p95 },
      m3c_perMoveScriptMs: m3cPerMove,
      m3c_tooltipAppeared: tooltipAppearedEveryRun,
      m3d_brushDrag: m3d, // non-null only for chart === "brush" (real handle-drag, see runOnce)
    },
    consoleErrorCount: consoleErrors.length,
    consoleErrorsSample: consoleErrors.slice(0, 5),
  };
}

// ---------------------------------------------------------------------- //
// Main
// ---------------------------------------------------------------------- //

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const baseUrl = args.baseUrl || BASE_URL;

  let combos = [];
  if (args.all) {
    for (const chart of CHARTS) {
      for (const impl of IMPLS) {
        for (const n of PILOT_NS) {
          combos.push({ impl, chart, n });
        }
      }
    }
  } else {
    if (!args.chart || !args.impl || !args.n) {
      console.error("Usage: node bench/run.mjs --chart <line|area|bar|scatter> --impl <bklit|tanstack> --n <int>");
      console.error("   or: node bench/run.mjs --all");
      process.exit(1);
    }
    combos = [{ impl: args.impl, chart: args.chart, n: args.n }];
  }

  const server = await ensureServer(baseUrl);
  const browser = await chromium.launch();
  const chromiumVersion = browser.version();

  const results = [];
  const skipped = [];
  try {
    for (const combo of combos) {
      console.log(`\n[bench] ${combo.impl}/${combo.chart} n=${combo.n}`);
      try {
        const r = await benchOne(browser, baseUrl, combo);
        results.push(r);
      } catch (err) {
        console.error(`[bench] SKIPPED ${combo.impl}/${combo.chart} n=${combo.n}: ${err.message}`);
        skipped.push({ ...combo, reason: err.message });
      }
    }
  } finally {
    await browser.close();
    await server.stop();
  }

  const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
  const outDir = path.join(RESULTS_DIR, timestamp);
  mkdirSync(outDir, { recursive: true });

  const payload = {
    timestamp: new Date().toISOString(),
    chromium: chromiumVersion,
    config: {
      warmupRuns: WARMUP_RUNS,
      measuredRuns: MEASURED_RUNS,
      idleMs: IDLE_MS,
      updateTicks: UPDATE_TICKS,
      hoverSteps: HOVER_STEPS,
    },
    results,
    skipped,
  };

  writeFileSync(path.join(outDir, "results.json"), JSON.stringify(payload, null, 2));
  writeFileSync(path.join(RESULTS_DIR, "latest.json"), JSON.stringify(payload, null, 2));

  console.log(`\n[bench] wrote ${results.length} result(s), ${skipped.length} skipped`);
  console.log(`[bench] -> ${path.join(outDir, "results.json")}`);
  console.log(`[bench] -> ${path.join(RESULTS_DIR, "latest.json")}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
